from rules import choose


def solve(data):
    packages = data["packages"]
    roots = data["roots"]
    names = sorted(packages)
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))

    if any(name not in packages for name in roots):
        return {"error": "unsatisfiable"}

    constraints = {
        name: [(bounds[0], bounds[1])]
        for name, bounds in roots.items()
    }
    best_key = None
    best_versions = None

    def active_dependencies(row):
        for dependency in row.get("deps", []):
            feature = dependency.get("feature")
            if feature and feature not in features:
                continue
            yield dependency

    def is_acyclic(assigned):
        graph = {name: [] for name in assigned}
        for name, row in assigned.items():
            for dependency in active_dependencies(row):
                graph[name].append(dependency["name"])

        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for neighbor in graph[name]:
                if not visit(neighbor):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(assigned, active_constraints):
        nonlocal best_key, best_versions

        unresolved = set(active_constraints) - set(assigned)
        if not unresolved:
            if not is_acyclic(assigned):
                return
            versions = {
                name: row["version"]
                for name, row in assigned.items()
            }
            key = tuple(versions.get(name, -1) for name in names)
            if best_key is None or key > best_key:
                best_key = key
                best_versions = versions
            return

        name = min(unresolved)
        for row in choose(
            packages[name],
            active_constraints[name],
            blocked.get(name, ()),
            pins.get(name),
        ):
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_constraints = {
                package: list(ranges)
                for package, ranges in active_constraints.items()
            }
            feasible = True

            for dependency in active_dependencies(row):
                dep_name = dependency["name"]
                if dep_name not in packages:
                    feasible = False
                    break

                low, high = dependency["min"], dependency["max"]
                next_constraints.setdefault(dep_name, []).append((low, high))
                if dep_name in next_assigned:
                    version = next_assigned[dep_name]["version"]
                    if not low <= version <= high:
                        feasible = False
                        break

            if feasible:
                search(next_assigned, next_constraints)

    search({}, constraints)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

def choose(rows, intervals=None, blocked=(), pin=None):
    if intervals is None:
        active_intervals = []
    elif (
        len(intervals) == 2
        and all(isinstance(value, int) for value in intervals)
    ):
        active_intervals = [intervals]
    else:
        active_intervals = intervals

    forbidden = set(blocked)
    eligible = [
        row for row in rows
        if row["version"] not in forbidden
        and (pin is None or row["version"] == pin)
        and all(
            low <= row["version"] <= high
            for low, high in active_intervals
        )
    ]
    return sorted(eligible, key=lambda row: row["version"], reverse=True)
